mod serial;

use std::{collections::HashMap, sync::LazyLock};

pub use serial::Serial;

static DISC_SETS: LazyLock<DiscSets> =
    LazyLock::new(|| DiscSets::parse(include_str!("discsets.tsv")));

/// Multidisc sets from shiragame, generated by `polymer-discsets`.
/// Each row of `discsets.tsv` is `platform, normalized serial, disc number, set name`.
pub struct DiscSets {
    serials: HashMap<(&'static str, &'static str), Vec<(u8, &'static str)>>,
    sets: HashMap<(&'static str, &'static str), Vec<(&'static str, u8)>>,
}

impl DiscSets {
    pub fn get() -> &'static Self {
        &DISC_SETS
    }

    fn parse(table: &'static str) -> Self {
        let mut serials = HashMap::<_, Vec<_>>::new();
        let mut sets = HashMap::<_, Vec<_>>::new();
        for line in table.lines() {
            let mut columns = line.splitn(4, '\t');
            let (Some(platform), Some(serial), Some(Ok(disc)), Some(set)) = (
                columns.next(),
                columns.next(),
                columns.next().map(str::parse::<u8>),
                columns.next(),
            ) else {
                continue;
            };
            serials
                .entry((platform, serial))
                .or_default()
                .push((disc, set));
            sets.entry((platform, set))
                .or_default()
                .push((serial, disc));
        }
        Self { serials, sets }
    }

    /// The header disc number, otherwise the table's when the serial names exactly one disc.
    pub fn disc(&self, platform: &str, serial: Option<&str>, header: Option<u8>) -> Option<u8> {
        header.or_else(|| {
            let serial = Serial::normalize(platform, serial?);
            let entries = self.serials.get(&(platform, serial.as_ref()))?;
            let (disc, _) = entries.first()?;
            entries
                .iter()
                .all(|(other, _)| other == disc)
                .then_some(*disc)
        })
    }

    /// The name of a set containing `serial` and the normalized serials of every first disc
    /// in the sets containing it.
    pub fn first_discs(
        &self,
        platform: &str,
        serial: &str,
    ) -> Option<(&'static str, Vec<&'static str>)> {
        let serial = Serial::normalize(platform, serial);
        let entries = self.serials.get(&(platform, serial.as_ref()))?;
        let firsts = entries
            .iter()
            .filter_map(|(_, set)| self.sets.get(&(platform, *set)))
            .flatten()
            .filter(|(_, disc)| *disc == 1)
            .map(|(serial, _)| *serial)
            .collect();
        Some((entries.first()?.1, firsts))
    }
}
